/* @autogenerated */
package net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.step;

import java.util.Arrays;
import java.util.List;
import java.util.Optional;
import java.util.Set;
import java.util.stream.Collectors;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.ws.rs.core.NewCookie;
import jakarta.ws.rs.core.Response;
import jakarta.ws.rs.core.Response.ResponseBuilder;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.oauth.authentication.domain.AuthRequest;
import net.civeira.phylax.features.oauth.authentication.domain.AuthenticationChallenge;
import net.civeira.phylax.features.oauth.authentication.domain.ChallengesState;
import net.civeira.phylax.features.oauth.authentication.domain.exception.AuthenticationException;
import net.civeira.phylax.features.oauth.authentication.domain.exception.ClientScopeConsentRequiredException;
import net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.AuthorizeHtml;
import net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.OidcResponseBuilder;
import net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.OidcStep;
import net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.SecureHtmlBuilder;
import net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.StepInput;
import net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.StepOutcome;
import net.civeira.phylax.features.oauth.consent.application.ScopeApprovalUsecase;
import net.civeira.phylax.features.oauth.consent.domain.ScopePermission;
import net.civeira.phylax.features.oauth.theme.domain.gateway.DecoratePageGateway;

/**
 * OIDC step for scope approval.
 *
 * <p>
 * Renders a consent form showing mandatory and optional scopes when
 * {@link ClientScopeConsentRequiredException} is thrown. Mandatory scopes are presented as
 * read-only entries; optional scopes are rendered as opt-in checkboxes. On submission only the
 * accepted scopes are stored and the {@link AuthRequest} is narrowed accordingly so the issued
 * token only carries approved scopes.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class ScopeConsentStep implements OidcStep {

  private static final String DENY_STEP = "scope_consent_deny";

  private final SecureHtmlBuilder securer;
  private final DecoratePageGateway decorator;
  private final ScopeApprovalUsecase scopeApprovalUsecase;
  private final OidcResponseBuilder responseBuilder;

  @Override
  public AuthenticationChallenge challenge() {
    return AuthenticationChallenge.CLIENT_CONSENT;
  }

  @Override
  public Class<? extends AuthenticationException> challengeException() {
    return ClientScopeConsentRequiredException.class;
  }

  @Override
  public Set<String> stepNames() {
    return Set.of("scope_consent", DENY_STEP);
  }

  @Override
  public Response paint(StepInput input, NewCookie preSession) {
    String username = input.currentUser().orElse("");
    return securer.secureHtmlResponse(buildForm(input, username, null).cookie(preSession));
  }

  /**
   * Stores the decision. A denial ends the request with {@code access_denied}; with
   * {@code prompt=consent} the requested scopes the user left unchecked lose their stored consent
   * (task 1.6). The request goes on with the accepted scopes only.
   */
  @Override
  public Optional<StepOutcome> process(StepInput input) {
    if (input.currentUser().isEmpty()) {
      return Optional.empty();
    }
    if (DENY_STEP.equals(input.step())) {
      return Optional.of(new StepOutcome.Render(responseBuilder.errorRedirect(input.getRequest(),
          "access_denied", "The user denied the requested scopes")));
    }
    if (!"scope_consent".equals(input.step())) {
      return Optional.empty();
    }
    String username = input.currentUser().get();
    String tenant = input.getRequest().getTenant();
    String clientId = input.getClientDetails().getClientId();
    List<String> acceptedScopes = input.getFormParams().getOrDefault("scope_accepted", List.of());
    scopeApprovalUsecase.storeApprovedScopes(tenant, username, clientId, acceptedScopes);
    if (input.getRequest().promptsConsent()) {
      scopeApprovalUsecase.withdrawScopes(tenant, username, clientId, requestedScopes(input)
          .stream().filter(scope -> !acceptedScopes.contains(scope)).toList());
    }
    AuthRequest narrowed =
        input.getRequest().toBuilder().scope(Optional.of(String.join(" ", acceptedScopes))).build();
    ChallengesState state = input.getChallenges().orElseGet(() -> ChallengesState.empty(username));
    return Optional
        .of(new StepOutcome.Proceed(username, input.getClientDetails(), narrowed, state));
  }

  private static List<String> requestedScopes(StepInput input) {
    return Arrays.stream(input.getRequest().getScope().orElse("").split("\\s+"))
        .filter(scope -> !scope.isBlank()).toList();
  }

  private ResponseBuilder buildForm(StepInput input, String username, String msg) {
    String clientId = input.getRequest().getClientId().orElse("");
    String scopeString = input.getRequest().getScope().orElse("");
    List<AuthenticationChallenge> completed =
        input.getChallenges().map(ChallengesState::getCompleted).orElse(List.of());
    String tenant = input.getRequest().getTenant();
    List<ScopePermission> pending = input.getRequest().promptsConsent()
        ? scopeApprovalUsecase.renewedApprovals(tenant, username, clientId, scopeString, completed)
        : scopeApprovalUsecase.pendingApprovals(tenant, username, clientId, scopeString, completed);

    List<ScopePermission> mandatory = pending.stream().filter(ScopePermission::isRequired).toList();
    List<ScopePermission> optional = pending.stream().filter(s -> !s.isRequired()).toList();

    String js = securer.configureScripts(securer.addSign("sign"));

    String title = AuthorizeHtml.i18n(input.locale(), "scopeconsent.title");
    String error = AuthorizeHtml.i18n(input.locale(), "scopeconsent.error-format", msg);
    String help = AuthorizeHtml.i18n(input.locale(), "scopeconsent.help");
    String accept = AuthorizeHtml.i18n(input.locale(), "scopeconsent.accept");
    String backLabel = AuthorizeHtml.i18n(input.locale(), "scopeconsent.back-label");
    String backText = AuthorizeHtml.i18n(input.locale(), "scopeconsent.back-text",
        "<input class=\"inline\" type=\"submit\" value=\"" + backLabel + "\" />");

    String mandatoryInputs = mandatory.stream()
        .map(s -> "<input type=\"hidden\" name=\"scope_accepted\" value=\"" + escape(s.getScope())
            + "\" />" + "<li class=\"scope-mandatory\">" + label(s) + "</li>")
        .collect(Collectors.joining());

    String optionalCheckboxes = optional.stream()
        .map(s -> "<li class=\"scope-optional\"><label>"
            + "<input type=\"checkbox\" name=\"scope_accepted\" value=\"" + escape(s.getScope())
            + "\" checked />" + " " + label(s) + "</label></li>")
        .collect(Collectors.joining());

    String scopeList = "<ul>" + mandatoryInputs + optionalCheckboxes + "</ul>";

    return Response.ok(decorator.getFullPage(input.tenant(), "scopeConsent",
        js + "<h1>" + title + "</h1>" + "<p>" + help + "</p>"
            + (null == msg ? "" : "<p class=\"error\">" + error + "</p>") + "<form method=\"POST\">"
            + "<input type=\"hidden\" name=\"csid\" id=\"sign\" />"
            + "<input type=\"hidden\" name=\"step\" value=\"scope_consent\" />" + scopeList
            + "<input class=\"primary-button action-button\" type=\"submit\" value=\"" + accept
            + "\" />" + "</form>" + "<form method=\"POST\">"
            + "<input type=\"hidden\" name=\"step\" value=\"" + DENY_STEP + "\" />" + "<p>"
            + backText + "</p>" + "</form>",
        input.locale())).type(AuthorizeHtml.TEXT_HTML);
  }

  private static String label(ScopePermission scope) {
    return escape(null != scope.getLabel() ? scope.getLabel() : scope.getScope());
  }

  private static String escape(String value) {
    return value.replace("&", "&amp;").replace("\"", "&quot;").replace("'", "&#39;")
        .replace("<", "&lt;").replace(">", "&gt;");
  }

}
